head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/pre_newlisting.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
scwin.clickBzProcsNo = "";
scwin.vScrenID = "ULDBNS20300.xml";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 설명       : 일자 조회
 ***********************************************/
scwin.fn_getDate = function() {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=ULDSTF41001_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.elwko.select.getPrevBusiDt";
    dts_getDate.DataID = encodeURI(url);
    dts_getDate.reset();
};


/********************************************** 
 * 함수명   : fn_GetParIsurCd
 * 설명       : 발행기관 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsurCd = function(arrPar) {
    arrPar[0] = {
        ISUR_CD: $c.stf.getObjectValue(txb_ISUR_CD)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_SetParIsurCd
 * 설명       : 발행기관 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParIsurCd = function(arrPar) {
    $c.stf.setObjectValue(txb_COM_NM, arrPar[0].ISUR_NM);
    $c.stf.setObjectValue(txb_ISUR_CD, arrPar[0].ISUR_CD);
};


/********************************************** 
 * 함수명   : fn_ShowIsur
 * 설명       : 발행기관 팝업을 보여준다.
 ***********************************************/
scwin.fn_ShowIsur = function(img_CoSearch) {
    scwin.fn_GetPar = fn_GetParIsurCd;
    scwin.fn_SetPar = fn_SetParIsurCd;
    $c.bns.fn_PopIsurSearch(img_CoSearch);
};


/********************************************** 
 * 설명       : 종목선택목록 세팅
 ***********************************************/
scwin.fn_SetParForIsuCd = function(arrPar) {
    txb_ISU_CD.setValue(arrPar[0].ISU_CD);
    txb_ISU_NM.setValue(arrPar[0].ISU_NM);
};



/********************************************** 
 * 함수명   : fn_GetParListBndIsu
 * 설명       : 상장종목 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParListBndIsu = function(arrPar) {
    arrPar[0] = {
        LIST_TYPE_CD: '2',
        ISUR_NM: $c.stf.getObjectValue(txb_ISUR_CD),
        ISU_NM: $c.stf.getObjectValue(txb_ISU_CD)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParListBndIsu
 * 설명       : 상장종목 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParListBndIsu = function(arrPar) {
    $c.stf.setObjectValue(txb_ISU_CD, arrPar[0].STD_CD);
    $c.stf.setObjectValue(txb_ISU_NM, arrPar[0].ISU_NM);
};


/********************************************** 
 * 설명       : 조회
 ***********************************************/
scwin.fn_Search = function() {
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_ANUL_FEE_PRE_INCOM_LIST";
    url += "&queryId=lds.stf.bnsanul_fee_pre_incom.select.list";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_CO_NM=" + txb_ISUR_CD.getValue();
    url += "&{P}V_ISU_NM=" + txb_ISU_CD.getValue();
    url += "&{P}V_GRP_YN=" + $c.stf.getObjectValue(cmb_GrpYn);
    url += "&{P}V_STD_DT=" + $c.stf.getObjectValue(edt_SDate);
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
    $c.cm.ShowWin(grd_List);
};


/********************************************** 
 * 설명       : 정보를 excel로 다운 받는다.
 ***********************************************/
scwin.fn_ExcelDown = function() {
    if (dts_List.getTotalRow() > 0) {
        //엑셀 로그 
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        var fileNm = $c.session.getExcelDownPath() + $c.ut.cGetToday("yyyymmddhhmmss") + "_연부과금 선수수익 조회.xls";
        //jackal_19.09.27  속도개선을 위해 수정 SaveExcel -> GridToExcel
        $c.data.downloadGridViewExcel(grd_List, "연부과금 선수수익 조회", "", "8");
    } else {
        $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};



/********************************************** 
 * 설명       : 연부과금 환급금 조회
 ***********************************************/
scwin.fn_Rpay_Amt = function() {
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_ANUL_FEE_PRE_INCOM_LISTAMT";
    url += "&queryId=lds.stf.bnsanul_fee_pre_incom.select.listamt";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_STD_DT=" + $c.stf.getObjectValue(edt_SDate);
    dts_RpayAmt.DataID = encodeURI(url);
    dts_RpayAmt.Reset();
    return Number(dts_RpayAmt.getCellData(0, "YAF_RPAY_AMT"));
};
scwin.gform_onload = function() {
    /********************************************** 
     * 함수명   : gform > onload
     * 설명      : 화면 Onload
     ***********************************************/
    $c.bns.BnsPanelToGroupBox(panel_Top);
    edt_SDate.setValue($c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 0));
};
scwin.btn_Search_onclick = function() {
    /********************************************** 
     * 함수명   : btn_Search > onclick
     * 설명      : 조회버튼 클릭
     ***********************************************/
    scwin.fn_Search();
};
scwin.img_CoSearch_onclick = function() {
    /********************************************** 
     * 함수명   : img_CoSearch > onclick
     * 설명      : 발행기관 조회
     ***********************************************/
    scwin.fn_ShowIsur(img_CoSearch);
};
scwin.btn_ISU_CD_SEARCH_onclick = function() {
    /********************************************** 
     * 함수명   : btn_ISU_CD_SEARCH > onclick
     * 설명      : 종목 조회
     ***********************************************/
    scwin.fn_GetPar = fn_GetParListBndIsu;
    scwin.fn_SetPar = fn_SetParListBndIsu;
    $c.bns.fn_PopListBndIsuSearch(btn_ISU_CD_SEARCH);
};
scwin.txb_ISUR_CD_onblur = function() {
    /********************************************** 
     * 함수명   : txb_ISUR_CD > onblur
     * 설명      : 발행기관 코드 변경
     ***********************************************/
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.txb_ISU_CD_onblur = function() {
    /********************************************** 
     * 함수명   : txb_ISU_CD > onblur
     * 설명      : 종목 코드 변경
     ***********************************************/
    if (txb_ISU_CD.getValue() == "") {
        txb_ISU_NM.setValue("");
    }
};
scwin.btn_SDate_onclick = function() {
    /********************************************** 
     * 함수명   : btn_SDate > onclick
     * 설명      : 신청일기간 시작일자 달력클릭
     ***********************************************/
    popUpCalendar2(edt_SDate);
};
scwin.btn_Excel_onclick = function() {
    /********************************************** 
     * 함수명   : btn_Excel > onclick
     * 설명      : 엑셀버튼 클릭
     ***********************************************/
    scwin.fn_ExcelDown();
};
scwin.dts_List_OnLoadError = function() {
    /********************************************** 
     * 함수명   : dts_List > OnLoadError
     * 설명      : dts_List 조회 에러 
     ***********************************************/
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    /********************************************** 
     * 함수명   : dts_List > OnLoadError
     * 설명      : dts_List 조회 성공
     ***********************************************/
    var sumNoTermYafFee = 0;
    var sumRpayYafAmt = 0;
    var minSumFeeAmt = 0;
    for (var i = 1; i <= dts_List.getTotalRow(); i++) {
        sumNoTermYafFee += Number(dts_List.getCellData(i, "BND_ANULFEE_MIN"));
    }
    if ($c.stf.getObjectValue(cmb_GrpYn) != "N") {
        sumRpayYafAmt = scwin.fn_Rpay_Amt();
    }
    minSumFeeAmt = sumNoTermYafFee - sumRpayYafAmt;
    grd_List.Redraw = false;
    dts_List.insertRow();
    dts_List.setCellData(rowcount + 1, "ISU_NM", "소계(①)");
    dts_List.setCellData(rowcount + 1, "BND_ANULFEE_MIN", sumNoTermYafFee);
    dts_List.insertRow();
    dts_List.setCellData(rowcount + 2, "ISU_NM", "연부과금 환급금 총액(②)");
    dts_List.setCellData(rowcount + 2, "BND_ANULFEE_MIN", sumRpayYafAmt);
    dts_List.insertRow();
    dts_List.setCellData(rowcount + 3, "ISU_NM", "선수수익 총액(① - ②)");
    dts_List.setCellData(rowcount + 3, "BND_ANULFEE_MIN", minSumFeeAmt);
    $c.stf.FillGridHeaderTotalCnt(rowcount + 3, panel_page);
    $c.cm.CloseWin(rowcount, grd_List);

    //grd_List.ColumnProp('NO','value') = "{decode(ISU_NM,'소계(①)','')}";
    $c.cm.setColumnProp(grd_List, 'NO', 'bgcolor', "{decode(ISU_NM,'소계(①)','#FFFF99','연부과금 환급금 총액(②)','#FFFF99','선수수익 총액(① - ②)','#FFFF99')}");
    $c.cm.setColumnProp(grd_List, 'GRP_YN', 'bgcolor', "{decode(ISU_NM,'소계(①)','#FFFF99','연부과금 환급금 총액(②)','#FFFF99','선수수익 총액(① - ②)','#FFFF99')}");
    $c.cm.setColumnProp(grd_List, 'ISU_NM', 'bgcolor', "{decode(ISU_NM,'소계(①)','#FFFF99','연부과금 환급금 총액(②)','#FFFF99','선수수익 총액(① - ②)','#FFFF99')}");
    $c.cm.setColumnProp(grd_List, 'BND_ANULFEE', 'bgcolor', "{decode(ISU_NM,'소계(①)','#FFFF99','연부과금 환급금 총액(②)','#FFFF99','선수수익 총액(① - ②)','#FFFF99')}");
    $c.cm.setColumnProp(grd_List, 'BND_TREM_AMT', 'bgcolor', "{decode(ISU_NM,'소계(①)','#FFFF99','연부과금 환급금 총액(②)','#FFFF99','선수수익 총액(① - ②)','#FFFF99')}");
    $c.cm.setColumnProp(grd_List, 'BND_ANULFEE_MIN', 'bgcolor', "{decode(ISU_NM,'소계(①)','#FFFF99','연부과금 환급금 총액(②)','#FFFF99','선수수익 총액(① - ②)','#FFFF99')}");
    $c.cm.setColumnProp(grd_List, 'TERM', 'bgcolor', "{decode(ISU_NM,'소계(①)','#FFFF99','연부과금 환급금 총액(②)','#FFFF99','선수수익 총액(① - ②)','#FFFF99')}");
    $c.cm.setColumnProp(grd_List, 'ISU_CD', 'bgcolor', "{decode(ISU_NM,'소계(①)','#FFFF99','연부과금 환급금 총액(②)','#FFFF99','선수수익 총액(① - ②)','#FFFF99')}");
    $c.cm.setColumnProp(grd_List, 'ISU_DD', 'bgcolor', "{decode(ISU_NM,'소계(①)','#FFFF99','연부과금 환급금 총액(②)','#FFFF99','선수수익 총액(① - ②)','#FFFF99')}");
    $c.cm.setColumnProp(grd_List, 'REDMPT_DD', 'bgcolor', "{decode(ISU_NM,'소계(①)','#FFFF99','연부과금 환급금 총액(②)','#FFFF99','선수수익 총액(① - ②)','#FFFF99')}");
    $c.cm.setColumnProp(grd_List, 'GRP_CNT', 'bgcolor', "{decode(ISU_NM,'소계(①)','#FFFF99','연부과금 환급금 총액(②)','#FFFF99','선수수익 총액(① - ②)','#FFFF99')}");
    $c.cm.setColumnProp(grd_List, 'GRP_TYP', 'bgcolor', "{decode(ISU_NM,'소계(①)','#FFFF99','연부과금 환급금 총액(②)','#FFFF99','선수수익 총액(① - ②)','#FFFF99')}");
    grd_List.Redraw = false;
    dts_List.setRowPosition(1, 0);
};
scwin.dts_RpayAmt_OnLoadError = function() {
    /********************************************** 
     * Event   : dts_RpayAmt > OnLoadError
     * 설명    : dts_RpayAmt 조회에러시 처리
     ***********************************************/
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_RpayAmt_OnLoadCompleted = function(rowcount) {
    /********************************************** 
     * Event   : dts_RpayAmt > OnLoadCompleted
     * 설명    : dts_RpayAmt 조회성공시 처리
     ***********************************************/
};
